import csv
import io
import unittest

from exporter import export_rows, NA_SENTINEL


def _parse(output):
    return list(csv.reader(io.StringIO(output)))


class ExportTests(unittest.TestCase):
    def test_header(self):
        self.assertTrue(export_rows([]).startswith("customer_id,region"))

    def test_missing_region_becomes_na(self):
        output = export_rows([{"customer_id": "007"}])
        self.assertEqual(_parse(output)[1], ["007", "NA"])

    def test_none_region_becomes_na(self):
        output = export_rows([{"customer_id": "008", "region": None}])
        self.assertEqual(_parse(output)[1], ["008", "NA"])

    def test_empty_region_stays_empty(self):
        output = export_rows([{"customer_id": "009", "region": ""}])
        self.assertEqual(_parse(output)[1], ["009", ""])

    def test_present_region_unchanged(self):
        output = export_rows([{"customer_id": "010", "region": "US"}])
        self.assertEqual(_parse(output)[1], ["010", "US"])

    def test_customer_id_preserved_with_leading_zeros(self):
        output = export_rows([{"customer_id": "000123", "region": "EU"}])
        self.assertEqual(_parse(output)[1], ["000123", "EU"])


if __name__ == "__main__":
    unittest.main()

